import { type FC, Fragment } from "react";
import type { Basics } from "../../../types/resume";
import { H1, H2, Text } from "../../atoms";

interface IHeroMainBlockProps {
  basic: Basics;
}

/**
 * Renders the hero's name/title and bio summary as two `[grid-area]`-tagged
 * fragments (no wrapping element) so they slot directly into HeroBlock's
 * `.hero-grid` alongside the photo and contact details, instead of nesting
 * a second copy of those inside this component. See docs/architecture.md.
 */
const MainBlock: FC<IHeroMainBlockProps> = ({ basic }) => {
  const heroText = basic.summary.split("\n");

  const text = Array.isArray(heroText) ? (
    heroText.map((text) => (
      <Fragment key={`heroText-${text}`}>
        <Text>{text}</Text>
      </Fragment>
    ))
  ) : (
    <Text>{heroText}</Text>
  );

  return (
    <>
      <div className="[grid-area:name] flex flex-col items-start">
        <H1>{basic.name}</H1>
        <H2 className="mt-4 print:mt-1">{basic.label}</H2>
      </div>
      <div className="[grid-area:summary] flex flex-col gap-8">{text}</div>
    </>
  );
};

export default MainBlock;
