// Callers construct `date` from partial ISO strings like "2022-01"
// (see experienceSubtitle.tsx, educationSubtitle.tsx,
// certificateSubtitle.tsx). Per the ECMA-262 Date Time String Format,
// `new Date("2022-01")` is parsed as UTC midnight. Formatting without a
// fixed `timeZone` renders in the viewer's local timezone, so anyone west
// of UTC would see the date rolled back by a day (often a whole month,
// e.g. "December 2021" instead of "January 2022"). Pinning `timeZone` to
// "UTC" keeps the rendered month/year consistent with the UTC instant the
// string was parsed as, for every viewer regardless of local timezone.
const MONTH_YEAR_RENDERER = new Intl.DateTimeFormat("en-GB", {
  year: "numeric",
  month: "long",
  timeZone: "UTC",
});

export function RenderYearMonth(date: Date): string {
  return MONTH_YEAR_RENDERER.format(date);
}
