import { ChevronRightIcon } from "@radix-ui/react-icons";
import {
  createContext,
  type FC,
  type PropsWithChildren,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useState,
} from "react";
import { twMerge } from "tailwind-merge";
import { getValueBoolean, setValueBoolean } from "../../../utils";

interface IAccordionContext {
  isOpen: boolean;
  setIsOpen: (state: boolean) => void;
  uniqueId?: string;
  /**
   * False until the persisted (localStorage) open/closed state has been
   * applied on mount. The server (and the very first client render) has
   * no way to know that value, so `isOpen` always starts `true`. While
   * `transitionsEnabled` is false, CSS transitions are suppressed so that
   * first correction - open on the server, possibly closed once the
   * persisted value is read - snaps instantly instead of visibly
   * animating (the "flash open, then animate closed" bug).
   */
  transitionsEnabled: boolean;
}

// `useLayoutEffect` is a no-op during Gatsby's server-side render (and logs
// a warning there, since layout effects need real DOM). Fall back to
// `useEffect` server-side; in the browser, `useLayoutEffect` lets us
// correct the open/closed state before the browser paints the hydrated
// frame, minimising the flash window.
const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? useLayoutEffect : useEffect;

const AccordionContext = createContext<IAccordionContext | undefined>(
  undefined,
);

const useAccordionContext = (): IAccordionContext => {
  const context = useContext(AccordionContext);

  if (!context) {
    throw new Error("Accordion Context is required");
  }

  return context;
};

interface IAccordionContentProps extends PropsWithChildren {
  className?: string;
}

interface IAccordionProps extends PropsWithChildren {
  uniqueId?: string;
}

interface IAccordion extends FC<IAccordionProps> {
  Trigger: FC<PropsWithChildren>;
  Content: FC<IAccordionContentProps>;
}

const sanitizeId = (id: string) => id.replaceAll(" ", "_");

const Accordion: IAccordion = ({ children, uniqueId }) => {
  const [isOpen, setIsOpen] = useState<boolean>(true);
  const [transitionsEnabled, setTransitionsEnabled] = useState(false);
  const sanitizedId = uniqueId && sanitizeId(uniqueId);

  // Correct `isOpen` from its SSR-safe default before the browser paints
  // the hydrated frame, while transitions are still suppressed.
  useIsomorphicLayoutEffect(() => {
    if (sanitizedId) {
      setIsOpen(getValueBoolean(sanitizedId));
    }
  }, [sanitizedId]);

  // Only re-enable transitions once that corrected state has actually been
  // painted. Doing this in the same effect as the `setIsOpen` correction
  // above would let React batch both updates into a single commit, so the
  // transition classes would land in the very same paint as the max-height
  // change they're meant to suppress - and, since the SSR "open" frame was
  // a real painted frame, the browser would still animate that change.
  // A plain (post-paint) effect guarantees a separate, later commit.
  useEffect(() => {
    setTransitionsEnabled(true);
  }, []);

  const setState = useCallback(
    (state: boolean) => {
      setIsOpen(state);

      if (sanitizedId) {
        setValueBoolean(sanitizedId, state);
      }
    },
    [sanitizedId],
  );

  return (
    <AccordionContext.Provider
      value={{
        isOpen,
        setIsOpen: setState,
        uniqueId: sanitizedId,
        transitionsEnabled,
      }}
    >
      {children}
    </AccordionContext.Provider>
  );
};

Accordion.Trigger = ({ children }) => {
  const { isOpen, setIsOpen, uniqueId, transitionsEnabled } =
    useAccordionContext();

  const onClick = useCallback(() => setIsOpen(!isOpen), [isOpen, setIsOpen]);

  if (!uniqueId) {
    return children;
  }

  return (
    <button
      id={`${uniqueId}-button`}
      onClick={onClick}
      type="button"
      aria-expanded={isOpen}
      aria-controls={`${uniqueId}-content`}
      className="flex flex-row"
    >
      <ChevronRightIcon
        className={twMerge(
          "print:hidden",
          "h-12 w-12 text-slate-700",
          transitionsEnabled && "transition-all duration-500 ease-in-out",
          isOpen && "rotate-90",
        )}
      />
      {children}
    </button>
  );
};

Accordion.Content = ({ children, className }) => {
  const { isOpen, uniqueId, transitionsEnabled } = useAccordionContext();
  return (
    <div
      id={uniqueId && `${uniqueId}-content`}
      className={twMerge(
        "print:max-h-[9999px]",
        "overflow-clip",
        transitionsEnabled && "transition-max-height duration-500 ease-in-out",
        isOpen ? "max-h-[9999px]" : "max-h-[0px]",
        className,
      )}
      aria-hidden={!isOpen}
    >
      {children}
    </div>
  );
};
export default Accordion;
