import { LinkedInLogoIcon } from "@radix-ui/react-icons";
import type { FC } from "react";
import type { Profile } from "../../../types/resume";
import { ExternalLink, FallbackIcon, GithubIcon } from "../../atoms";

interface IProfileBlockProps {
  profile: Profile;
  name: string;
}

/**
 * Unrecognised networks (e.g. a typo in resume.json) fall back to a generic
 * icon instead of throwing - a bad data value shouldn't white-screen the
 * whole page. See docs/error-handling.md.
 */
const networkToIcon = (network: string) => {
  switch (network.toLowerCase()) {
    case "linkedin":
      return <LinkedInLogoIcon className="inline h-5 w-5" />;
    case "github":
      return <GithubIcon className="inline" />;
    default:
      if (process.env.NODE_ENV !== "production") {
        console.warn(
          `networkToIcon: no icon mapped for "${network}", using fallback`,
        );
      }
      return <FallbackIcon className="inline h-5 w-5" />;
  }
};

const ProfileBlock: FC<IProfileBlockProps> = ({ profile, name }) => {
  return (
    <ExternalLink
      label={`External link to ${name}'s ${profile.network}`}
      href={profile.url}
    >
      {networkToIcon(profile.network)}
      <span className="hidden print:inline print:ml-1">{profile.username}</span>
    </ExternalLink>
  );
};

export default ProfileBlock;
