import type { FC, ReactNode } from "react";
import type { Basics } from "../../../types/resume";
import { ExternalLink } from "../../atoms";
import ContactBlock from "../../molecules/contactBlock/contactBlock";
import MainBlock from "./mainBlock";

const ctaButtonClass =
  "inline-flex items-center justify-center gap-1 rounded-md px-4 py-2 text-sm font-semibold";

export interface IHeroBlockProps {
  basic: Basics;
  profileImage: ReactNode;
}

interface IPrivateContactDetails {
  mobile: string;
  email: string;
}

// GATSBY_-prefixed env vars are inlined at build time, so they're available
// synchronously during render (both SSR and client). Reading them here
// (rather than behind a useState/useEffect) means the print-only contact
// details are present on first paint, not only after hydration completes.
// See docs/print-contact-details.md.
//
// Gatsby's webpack config inlines each `process.env.KEY` member expression
// individually (and replaces the bare `process.env` identifier with `{}`),
// so these must be read via direct member access — destructuring
// `process.env` would defeat the inlining and always evaluate to
// `undefined` in built bundles.
const getPrivateContactDetails = (): IPrivateContactDetails | undefined => {
  const mobile = process.env.GATSBY_MOBILE;
  const email = process.env.GATSBY_EMAIL;

  return mobile && email ? { mobile, email } : undefined;
};

const HeroBlock: FC<IHeroBlockProps> = ({ basic, profileImage }) => {
  const privateContactDetails = getPrivateContactDetails();
  const linkedIn = basic.profiles.find(
    (profile) => profile.network.toLowerCase() === "linkedin",
  );

  return (
    <section className="hero-grid w-full print:w-full">
      <MainBlock basic={basic} />
      <div className="[grid-area:photo] max-w-16">{profileImage}</div>
      <div className="[grid-area:contact]">
        <ContactBlock profiles={basic.profiles} {...privateContactDetails} />
      </div>
      <div className="[grid-area:cta] print:hidden flex flex-row flex-wrap gap-3">
        {linkedIn && (
          <ExternalLink
            href={linkedIn.url}
            label={`Connect with ${basic.name} on LinkedIn`}
            className={`${ctaButtonClass} bg-slate-700 text-white hover:bg-slate-600`}
          >
            Connect on LinkedIn
          </ExternalLink>
        )}
        <button
          type="button"
          onClick={() => window.print()}
          className={`${ctaButtonClass} border border-slate-700 text-slate-700 hover:bg-slate-100`}
        >
          Download PDF Resume
        </button>
      </div>
    </section>
  );
};

export default HeroBlock;
