import {
  ActivityLogIcon,
  EnvelopeClosedIcon,
  HandIcon,
  LapTimerIcon,
  LayersIcon,
  LightningBoltIcon,
  LinkBreak2Icon,
  MixIcon,
  Pencil2Icon,
  PersonIcon,
  ReaderIcon,
  RulerSquareIcon,
  Share1Icon,
} from "@radix-ui/react-icons";
import type { ReactNode } from "react";
import {
  AngularJsIcon,
  AWSIcon,
  BashIcon,
  BitbucketIcon,
  CIcon,
  CPlusPlusIcon,
  CSharpIcon,
  DJangoIcon,
  DockerIcon,
  DynamoDBIcon,
  FallbackIcon,
  GithubIcon,
  GitIcon,
  IonicIcon,
  JavaIcon,
  JenkinsIcon,
  LagomIcon,
  LinuxIcon,
  MongoDBIcon,
  MySQLIcon,
  NestJSIcon,
  PostgreSQLIcon,
  PythonIcon,
  ReactIcon,
  RedisIcon,
  SpringIcon,
  StrapiIcon,
  TerraformIcon,
  TerragruntIcon,
  TypescriptIcon,
} from "../components/atoms";

/**
 * Lookup map of lowercased skill/duty icon name -> icon factory. Keeping
 * this data-driven (rather than a switch) makes the fallback case (an
 * unrecognised name) a single `undefined` lookup instead of a `default`
 * branch that's easy to forget to update, and keeps names/icons declared
 * once instead of split across `case`/`return` pairs.
 *
 * Icons are still statically imported above, so webpack can't drop unused
 * branches from the bundle (see docs/data-flow.md#icon-resolution) - the
 * icon set is tiny inline SVG today, so that tradeoff is left as-is rather
 * than moving to dynamic imports, which would complicate SSR for little
 * benefit at this scale.
 */
const ICONS: Record<string, () => ReactNode> = {
  //#region Programming Languages
  java: () => <JavaIcon />,
  python: () => <PythonIcon />,
  typescript: () => <TypescriptIcon />,
  bash: () => <BashIcon />,
  "c#": () => <CSharpIcon />,
  c: () => <CIcon />,
  "c++": () => <CPlusPlusIcon />,
  "c/c++": () => (
    <>
      <CIcon width={10} height={10} />
      <CPlusPlusIcon width={10} height={10} />
    </>
  ),
  //#endregion
  //#region Databases
  mysql: () => <MySQLIcon />,
  redis: () => <RedisIcon />,
  dynamodb: () => <DynamoDBIcon />,
  postgresql: () => <PostgreSQLIcon />,
  mongodb: () => <MongoDBIcon />,
  //#endregion
  //#region Frameworks/Platforms/Libraries
  angularjs: () => <AngularJsIcon />,
  django: () => <DJangoIcon />,
  spring: () => <SpringIcon />,
  nestjs: () => <NestJSIcon />,
  react: () => <ReactIcon />,
  lagom: () => <LagomIcon />,
  ionic: () => <IonicIcon />,
  strapi: () => <StrapiIcon />,
  //#endregion
  //#region Devops
  "bitbucket pipelines": () => <BitbucketIcon />,
  "github actions": () => <GithubIcon />,
  aws: () => <AWSIcon />,
  jenkins: () => <JenkinsIcon />,
  terraform: () => <TerraformIcon />,
  terragrunt: () => <TerragruntIcon />,
  docker: () => <DockerIcon />,
  //#endregion
  //#region Other
  git: () => <GitIcon />,
  "system design": () => <Pencil2Icon className="mt-0.5" />,
  "agile methodologies": () => <LightningBoltIcon className="mt-0.5" />,
  "stakeholder communication": () => <EnvelopeClosedIcon className="mt-0.5" />,
  linux: () => <LinuxIcon />,
  //#endregion
  //#region experience
  ruler: () => <RulerSquareIcon className="mt-0.5" />,
  reader: () => <ReaderIcon className="mt-0.5" />,
  mix: () => <MixIcon className="mt-0.5" />,
  person: () => <PersonIcon className="mt-0.5" />,
  share: () => <Share1Icon className="mt-0.5" />,
  timer: () => <LapTimerIcon className="mt-0.5" />,
  layers: () => <LayersIcon className="mt-0.5" />,
  activity: () => <ActivityLogIcon className="mt-0.5" />,
  break: () => <LinkBreak2Icon className="mt-0.5" />,
  hand: () => <HandIcon className="mt-0.5" />,
  //#endregion
};

export function toIcon(name: string): ReactNode {
  const icon = ICONS[name.toLowerCase()];
  if (icon) {
    return icon();
  }
  if (process.env.NODE_ENV !== "production") {
    console.warn(`toIcon: no icon mapped for "${name}", using fallback`);
  }
  // Match the 15x15 default size of the sibling Radix icons above.
  return <FallbackIcon width={15} height={15} className="mt-0.5" />;
}
