import { graphql, type HeadFC, type PageProps, useStaticQuery } from "gatsby";
import { StaticImage } from "gatsby-plugin-image";
import type { FC } from "react";
import { MainLayout } from "../components/layouts/mainLayout";
import { HeroBlock } from "../components/organisms";
import { ExperienceSection, SkillSection } from "../components/templates";
import EducationCertificationSection from "../components/templates/educationSection/educationSection";
import { ResumeProvider } from "../context";
import resume from "../data/resume.json";
import type { ResumeSchema } from "../types/resume";

const TypedResume = resume as ResumeSchema;

const SITE_TITLE = "Marcus Gilmore-Lim";
const SITE_DESCRIPTION =
  "The portfolio of Marcus Gilmore-Lim, a Senior Software Engineer with 10 years of experience in building robust, scalable systems. A programming polyglot specializing in Java, Python, C#, cloud architecture, and DevOps.";

type SiteMetadataQueryResult = {
  site: {
    siteMetadata: {
      siteUrl: string | null;
    } | null;
  } | null;
};

const IndexPage: FC<PageProps> = () => {
  return (
    <MainLayout>
      <ResumeProvider resume={TypedResume}>
        <HeroBlock
          basic={TypedResume.basics}
          profileImage={
            <StaticImage
              src={"../images/marcus-gilmore-lim.jpg"}
              alt="A picture of Marcus Gilmore"
              imgClassName="w-full h-auto object-cover rounded-full"
            />
          }
        />
        <SkillSection skills={TypedResume.skills} />
        <ExperienceSection works={TypedResume.work} />
        <EducationCertificationSection
          educations={TypedResume.education}
          certificates={TypedResume.certificates}
        />
      </ResumeProvider>
    </MainLayout>
  );
};

export default IndexPage;

export const Head: HeadFC = () => {
  const { site } = useStaticQuery<SiteMetadataQueryResult>(graphql`
    query SeoSiteMetadata {
      site {
        siteMetadata {
          siteUrl
        }
      }
    }
  `);

  const rawSiteUrl = site?.siteMetadata?.siteUrl;
  if (!rawSiteUrl) {
    // gatsby-config.ts always sets siteMetadata.siteUrl, but Gatsby's
    // inferred GraphQL schema doesn't guarantee it's non-null, so fail
    // loudly at build time rather than emitting a canonical/OG url of
    // "undefined" (the same failure mode the previous `as string` cast
    // silently masked).
    throw new Error(
      "siteMetadata.siteUrl is not set - check siteUrl in gatsby-config.ts",
    );
  }
  // Strip any trailing slash so joined URLs (e.g. the OG image) never end
  // up with a double slash.
  const siteUrl = rawSiteUrl.replace(/\/+$/, "");
  const ogImageUrl = `${siteUrl}/og-image.jpg`;

  return (
    <>
      <html lang="en" />
      <title>{SITE_TITLE}</title>
      <meta name="description" content={SITE_DESCRIPTION} />
      <link rel="canonical" href={siteUrl} />
      <link rel="icon" type="image/png" href="/favicon.png" />

      <meta property="og:type" content="website" />
      <meta property="og:url" content={siteUrl} />
      <meta property="og:title" content={SITE_TITLE} />
      <meta property="og:description" content={SITE_DESCRIPTION} />
      <meta property="og:image" content={ogImageUrl} />

      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:title" content={SITE_TITLE} />
      <meta name="twitter:description" content={SITE_DESCRIPTION} />
      <meta name="twitter:image" content={ogImageUrl} />
    </>
  );
};
